    private static Resource? ResourceValue(Variant value)=>value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;
    private readonly PowderMaterialOperations _material=new();private readonly PowderSourceOperations _source=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorDataOperations _data=new();
    private static GArray Names()=>GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_material.gd").GetScriptConstantMap()["NAMES"].AsGodotArray();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static Resource? Reference(Resource actor)=>ResourceValue(Get(actor.Get("values").AsGodotDictionary(),"powder_material"));
    public void setup(VBoxContainer owner,RefCounted model,Resource actor,Variant refresh)
    {
        owner.Name="PowderMaterialBrowser";var row=new HBoxContainer();owner.AddChild(row);var choice=new OptionButton{Name="PowderPreset",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};var names=Names();for(int i=0;i<names.Count;i++)choice.AddIconItem(thumbnail(i),names[i].AsString());var reference=Reference(actor);var current=reference!=null?_animation.resolve_reference(reference):null;if(current!=null)choice.Select(Math.Max(0,names.IndexOf(Get(current.Get("values").AsGodotDictionary(),"preset_origin","").AsString())));row.AddChild(choice);var options=new HBoxContainer();owner.AddChild(options);var mode=new OptionButton{Name="PowderPresetMode",TooltipText="Apply physical defaults, visual appearance, or both. Existing actor source and timeline timing are preserved.",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};foreach(string title in new[]{"Both","Appearance only","Physics only"})mode.AddItem(title);options.AddChild(mode);var apply=new Button{Name="ApplyPowderPreset",Text="✓",TooltipText="Apply selected recipe",CustomMinimumSize=new Vector2(30,0)};row.AddChild(apply);apply.Pressed+=()=>{var selected=model.Call("selected_actors").AsGodotArray();_material.apply(model,selected.Contains(actor)?selected:new GArray{actor},_data.from_object(_material.preset(choice.Selected)),mode.Selected);owner.Call("_refresh",refresh);};var actions=new MenuButton{Text="⋯",TooltipText="Create from current settings, adopt saved physics or restore defaults"};options.AddChild(actions);foreach(string title in new[]{"Create material from current settings","Adopt saved physics defaults","Restore built-in recipe","Save attached deposits as mesh…","Reactivate deposits now"})actions.GetPopup().AddItem(title);actions.GetPopup().IdPressed+=action=>{switch(action){case 0:_material.apply(model,new GArray{actor},_data.from_object(_material.capture(actor)),1);break;case 1:_material.apply(model,new GArray{actor},Reference(actor),2);break;case 2:var attached=Reference(actor);var data=attached!=null?_animation.resolve_reference(attached):null;int index=data!=null?names.IndexOf(Get(data.Get("values").AsGodotDictionary(),"preset_origin","Sand").AsString()):0;_material.apply(model,new GArray{actor},_data.from_object(_material.preset(Math.Max(0,index))),0);break;case 3:GD.Load<GDScript>("res://scripts/actors/physics/physics_mesh_snapshot.gd").Call("prompt",owner,model,actor,true);break;case 4:foreach(var editor in owner.GetTree().GetNodesInGroup("actor_timeline_editors")){if(editor.Get("model").AsGodotObject()!=model)continue;double at=actor.Get("animation_time").AsDouble();model.Call("edit_property",actor,editor.Get("registry").AsGodotObject().Call("get_definition",new StringName("powder")),new StringName("powder_clear_at"),Math.Max(0,double.IsNaN(at)?0:at));}break;}owner.Call("_refresh",refresh);};var note=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart,Text="Independent actor physics",TooltipText="Recipes provide defaults. Existing actor physical controls remain authoritative. Grain shapes are visual; collisions remain spherical."};note.AddThemeFontSizeOverride("font_size",12);owner.AddChild(note);
