    public Texture2D thumbnail(int index){var data=_material.preset(index);var values=data.Get("values").AsGodotDictionary();using var image=Image.CreateEmpty(40,30,false,Image.Format.Rgba8);image.Fill(new Color("182430"));using var rng=_source.rng_for(index,100);for(int grain=0;grain<7;grain++){var center=new Vector2(rng.RandfRange(5,35),rng.RandfRange(5,25));float radius=rng.RandfRange(2,5);var color=values["powder_color"].AsColor().Lerp(values["powder_secondary"].AsColor(),rng.Randf());for(int y=Math.Max(0,(int)(center.Y-radius));y<Math.Min(30,(int)(center.Y+radius)+1);y++)for(int x=Math.Max(0,(int)(center.X-radius));x<Math.Min(40,(int)(center.X+radius)+1);x++){var delta=new Vector2(x,y)-center;double shape=index==4?1:.85+.15*Math.Cos(delta.Angle()*new[]{5,4,7,6,1,4,6}[index]);if(delta.Length()<radius*shape)image.SetPixel(x,y,color*(float)(.7+.3*(1-delta.Y/radius)));}}return ImageTexture.CreateFromImage(image);}
